const menuButton=document.querySelector('.menu-toggle');
const menu=document.querySelector('.menu-overlay');const main=document.querySelector('main');
let lastFocus=null;
function setMenu(open){if(open)lastFocus=document.activeElement;menu.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);menu.inert=!open;main.inert=open;menuButton.setAttribute('aria-expanded',String(open));menuButton.querySelector('.menu-label').textContent=open?'CLOSE':'MENU';if(open)menu.querySelector('a').focus();else if(lastFocus===menuButton||menu.contains(document.activeElement))menuButton.focus();}
menuButton.addEventListener('click',()=>setMenu(!menu.classList.contains('is-open')));
menu.querySelectorAll('[data-menu-link]').forEach(link=>link.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.classList.contains('is-open'))setMenu(false);if(event.key==='Tab'&&menu.classList.contains('is-open')){const links=[...menu.querySelectorAll('a')];const first=links[0],last=links[links.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();menuButton.focus()}else if(event.shiftKey&&document.activeElement===menuButton){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();menuButton.focus()}else if(!event.shiftKey&&document.activeElement===menuButton){event.preventDefault();first.focus()}}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if('IntersectionObserver'in window&&!reduced.matches){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.12,rootMargin:'0px 0px -30px 0px'});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}else document.querySelectorAll('.reveal').forEach(el=>el.classList.add('is-visible'));
const gallery=document.querySelector('.dome-gallery');if(gallery){const items=[...gallery.querySelectorAll('.dome-item')];const counter=document.querySelector('.gallery-counter');let active=0;const mobile=matchMedia('(max-width: 760px)');
function displayGallery(scroll=true){items.forEach((item,i)=>{let delta=i-active;if(delta>2)delta-=items.length;if(delta< -2)delta+=items.length;item.dataset.pos=String(delta);item.classList.toggle('is-active',i===active);item.setAttribute('aria-hidden',String(!mobile.matches&&Math.abs(delta)>1))});counter.innerHTML=String(active+1).padStart(2,'0')+' <i>/</i> '+String(items.length).padStart(2,'0');if(mobile.matches&&scroll)items[active].scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'nearest',inline:'center'})}
function moveGallery(direction){active=(active+direction+items.length)%items.length;displayGallery()}
document.querySelector('.gallery-prev').addEventListener('click',()=>moveGallery(-1));document.querySelector('.gallery-next').addEventListener('click',()=>moveGallery(1));
let startX=null;gallery.addEventListener('pointerdown',event=>{if(!mobile.matches)startX=event.clientX});gallery.addEventListener('pointerup',event=>{if(startX!==null&&Math.abs(event.clientX-startX)>45)moveGallery(event.clientX<startX?1:-1);startX=null});
let scrollTimer;gallery.addEventListener('scroll',()=>{if(!mobile.matches)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{const center=gallery.getBoundingClientRect().left+gallery.clientWidth/2;active=items.reduce((best,item,i)=>Math.abs(item.getBoundingClientRect().left+item.clientWidth/2-center)<Math.abs(items[best].getBoundingClientRect().left+items[best].clientWidth/2-center)?i:best,active);displayGallery(false)},90)},{passive:true});mobile.addEventListener('change',()=>displayGallery(false));displayGallery(false);
}document.getElementById('year').textContent=new Date().getFullYear();
